def self.slice_multi_event(time_array, record_array, index, num)
  times = time_array.slice(index, num)
  records = record_array.slice(index, num)
  Fluent::MultiEventStream.new(times, records)
end

def self.dup_multi_event(time_array, record_array)
  copied_times = time_array.dup
  copied_records = record_array.map(&:dup)
  Fluent::MultiEventStream.new(copied_times, copied_records)
end

private

def io_handler(watcher, path)
  TailWatcher::IOHandler.new(
    watcher,
    path: path,
    log: log,
    read_lines_limit: @read_lines_limit,
    read_bytes_limit_per_second: @read_bytes_limit_per_second,
    open_on_every_update: @open_on_every_update,
    from_encoding: @from_encoding,
    encoding: @encoding,
    &method(:receive_lines)
  )
end

class StatWatcher < Coolio::StatWatcher
  def initialize(path, log, &callback)
    @callback = callback
    @log = log
    super(path)
  end

  def on_change(prev, cur)
    @callback.call
  rescue
    @log.error $!.to_s
    @log.error_backtrace
  end
end

class TimerTrigger < Coolio::TimerWatcher
  def initialize(interval, log, &callback)
    @log = log
    @callback = callback
    super(interval, true)
  end

  def on_timer
    @callback.call
  rescue => e
    @log.error e.to_s
    @log.error_backtrace
  end
end

class TailWatcher
  def initialize(target_info, pe, log, read_from_head, follow_inodes, update_watcher, line_buffer_timer_flusher, io_handler_build)
    @path = target_info.path
    @ino = target_info.ino
    @pe = pe || MemoryPositionEntry.new
    @read_from_head = read_from_head
    @follow_inodes = follow_inodes
    @update_watcher = update_watcher
    @log = log
    @rotate_handler = RotateHandler.new(log, &method(:on_rotate))
    @line_buffer_timer_flusher = line_buffer_timer_flusher
    @io_handler = nil
    @io_handler_build = io_handler_build
    @watchers = []
  end

  attr_reader :path, :ino
  attr_reader :pe
  attr_reader :line_buffer_timer_flusher
  attr_accessor :unwatched  # This is used for removing position entry from PositionFile
  attr_reader :watchers

  def tag
    @parsed_tag ||= @path.tr('/', '.').gsub(/\.+/, '.').gsub(/^\./, '')
  end

  def register_watcher(watcher)
    @watchers << watcher
  end

  def detach(shutdown_start_time = nil)
    if @io_handler
      @io_handler.ready_to_shutdown(shutdown_start_time)
      @io_handler.on_notify
    end
    @line_buffer_timer_flusher&.close(self)
  end

  def close
    if @io_handler
      @io_handler.close
      @io_handler = nil
    end
  end

  def eof?
    @io_handler.eof?
  end

  def on_notify
    begin
      stat = Fluent::FileWrapper.stat(@path)
    rescue Errno::ENOENT, Errno::EACCES
      # moved or deleted
      stat = nil
    end

    @rotate_handler.on_notify(stat) if @rotate_handler
    @line_buffer_timer_flusher.on_notify(self) if @line_buffer_timer_flusher
    @io_handler.on_notify if @io_handler
  end

  def on_rotate(stat)
    if @io_handler.nil?
      if stat
        # first time
        fsize = stat.size
        inode = stat.ino

        last_inode = @pe.read_inode
        if inode == last_inode
          # rotated file has the same inode number with the last file.
          # assuming following situation:
          #   a) file was once renamed and backed, or
          #   b) symlink or hardlink to the same file is recreated
          # in either case of a and b, seek to the saved position
          #   c) file was once renamed, truncated and then backed
          # in this case, consider it truncated
          @pe.update(inode, 0) if fsize < @pe.read_pos
        elsif last_inode != 0
          # this is FilePositionEntry and fluentd once started.
          # read data from the head of the rotated file.
          # logs never duplicate because this file is a rotated new file.
          @pe.update(inode, 0)
        else
          # this is MemoryPositionEntry or this is the first time fluentd started.
          # seek to the end of the any files.
          # logs may duplicate without this seek because it's not sure the file is
          # existent file or rotated new file.
          pos = @read_from_head ? 0 : fsize
          @pe.update(inode, pos)
        end
        @io_handler = io_handler
      else
        @io_handler = NullIOHandler.new
      end
    else
      watcher_needs_update = false

      if stat
        inode = stat.ino
        if inode == @pe.read_inode # truncated
          @pe.update_pos(0)
          @io_handler.close
        elsif !@io_handler.opened? # There is no previous file. Reuse TailWatcher
          @pe.update(inode, 0)
        else # file is rotated and new file found
          watcher_needs_update = true
          # Handle the old log file before renewing TailWatcher [fluentd#1055]
          @io_handler.on_notify
        end
      else # file is rotated and new file not found
        # Clear RotateHandler to avoid duplicated file watch in same path.
        @rotate_handler = nil
        watcher_needs_update = true
      end

      if watcher_needs_update
        if @follow_inodes
          # No need to update a watcher if stat is nil (file not present), because moving to inodes will create
          # new watcher, and old watcher will be closed by stop_watcher in refresh_watchers method
          # don't want to swap state because we need latest read offset in pos file even after rotate_wait
          if stat
            target_info = TargetInfo.new(@path, stat)
            @update_watcher.call(target_info, @pe)
          end
        else
          # Permit to handle if stat is nil (file not present).
          # If a file is mv-ed and a new file is created during
          # calling `#refresh_watchers`s, and `#refresh_watchers` won't run `#start_watchers`
          # and `#stop_watchers()` for the path because `target_paths_hash`
          # always contains the path.
          target_info = TargetInfo.new(@path, stat ? stat.ino : nil)
          @update_watcher.call(target_info, swap_state(@pe))
        end
      else
        @log.info "detected rotation of #{@path}"
        @io_handler = io_handler
      end
    end
  end

  def io_handler
    @io_handler_build.call(self, @path)
  end

  def swap_state(pe)
    # Use MemoryPositionEntry for rotated file temporary
    mpe = MemoryPositionEntry.new
    mpe.update(pe.read_inode, pe.read_pos)
    @pe = mpe
    pe # This pe will be updated in on_rotate after TailWatcher is initialized
  end

  class FIFO
    def initialize(from_encoding, encoding)
      @from_encoding = from_encoding
      @encoding = encoding
      @need_enc = from_encoding != encoding
      @buffer = ''.force_encoding(from_encoding)
      @eol = "\n".encode(from_encoding).freeze
    end

    attr_reader :from_encoding, :encoding, :buffer

    def <<(chunk)
      # Although "chunk" is most likely transient besides String#force_encoding itself
      # won't affect the actual content of it, it is also probable that "chunk" is
      # a reused buffer and changing its encoding causes some problems on the caller side.
      #
      # Actually, the caller here is specific and "chunk" comes from IO#partial with
      # the second argument, which the function always returns as a return value.
      #
      # Feeding a string that has its encoding attribute set to any double-byte or
      # quad-byte encoding to IO#readpartial as the second arguments results in an
      # assertion failure on Ruby < 2.4.0 for unknown reasons.
      orig_encoding = chunk.encoding
      chunk.force_encoding(from_encoding)
      @buffer << chunk
      # Thus the encoding needs to be reverted back here
      chunk.force_encoding(orig_encoding)
    end

    def convert(s)
      if @need_enc
        s.encode!(@encoding, @from_encoding)
      else
        s
      end
    rescue
      s.encode!(@encoding, @from_encoding, :invalid => :replace, :undef => :replace)
    end

    def read_lines(lines)
      idx = @buffer.index(@eol)

      until idx.nil?
        # Using freeze and slice is faster than slice!
        # See https://github.com/fluent/fluentd/pull/2527
        @buffer.freeze
        rbuf = @buffer.slice(0, idx + 1)
        @buffer = @buffer.slice(idx + 1, @buffer.size)
        idx = @buffer.index(@eol)
        lines << convert(rbuf)
      end
    end

    def bytesize
      @buffer.bytesize
    end
  end

  class IOHandler
    BYTES_TO_READ = 8192
    SHUTDOWN_TIMEOUT = 5

    attr_accessor :shutdown_timeout

    def initialize(watcher, path:, read_lines_limit:, read_bytes_limit_per_second:, log:, open_on_every_update:, from_encoding: nil, encoding: nil, &receive_lines)
      @watcher = watcher
      @path = path
      @read_lines_limit = read_lines_limit
      @read_bytes_limit_per_second = read_bytes_limit_per_second
      @receive_lines = receive_lines
      @open_on_every_update = open_on_every_update
      @fifo = FIFO.new(from_encoding || Encoding::ASCII_8BIT, encoding || Encoding::ASCII_8BIT)
      @iobuf = ''.force_encoding('ASCII-8BIT')
      @lines = []
      @io = nil
      @notify_mutex = Mutex.new
      @log = log
      @start_reading_time = nil
      @number_bytes_read = 0
      @shutdown_start_time = nil
      @shutdown_timeout = SHUTDOWN_TIMEOUT
      @shutdown_mutex = Mutex.new
      @eof = false

      @log.info "following tail of #{@path}"
    end

    def on_notify
      @notify_mutex.synchronize { handle_notify }
    end

    def ready_to_shutdown(shutdown_start_time = nil)
      @shutdown_mutex.synchronize {
        @shutdown_start_time =
          shutdown_start_time || Fluent::Clock.now
      }
    end

    def close
      if @io && !@io.closed?
        @io.close
        @io = nil
      end
    end

    def opened?
      !!@io
    end

    def eof?
      @eof
    end

    private

    def limit_bytes_per_second_reached?
      return false if @read_bytes_limit_per_second < 0 # not enabled by conf
      return false if @number_bytes_read < @read_bytes_limit_per_second

      @start_reading_time ||= Fluent::Clock.now
      time_spent_reading = Fluent::Clock.now - @start_reading_time
      @log.debug("time_spent_reading: #{time_spent_reading} #{ @watcher.path}")

      if time_spent_reading < 1
        true
      else
        @start_reading_time = nil
        @number_bytes_read = 0
        false
      end
    end

    def should_shutdown_now?
      # Ensure to read all remaining lines, but abort immediately if it
      # seems to take too long time.
      @shutdown_mutex.synchronize {
        return false if @shutdown_start_time.nil?
        return Fluent::Clock.now - @shutdown_start_time > @shutdown_timeout
      }
    end

    def handle_notify
      return if limit_bytes_per_second_reached?

      with_io do |io|
        begin
          read_more = false

          if !io.nil? && @lines.empty?
            begin
              while true
                @start_reading_time ||= Fluent::Clock.now
                data = io.readpartial(BYTES_TO_READ, @iobuf)
                @eof = false
                @number_bytes_read += data.bytesize
                @fifo << data
                @fifo.read_lines(@lines)

                if limit_bytes_per_second_reached? || should_shutdown_now?
                  # Just get out from tailing loop.
                  read_more = false
                  break
                end
                if @lines.size >= @read_lines_limit
                  # not to use too much memory in case the file is very large
                  read_more = true
                  break
                end
              end
            rescue EOFError
              @eof = true
            end
          end

          unless @lines.empty?
            if @receive_lines.call(@lines, @watcher)
              @watcher.pe.update_pos(io.pos - @fifo.bytesize)
              @lines.clear
            else
              read_more = false
            end
          end
        end while read_more
      end
    end

    def open

    break if before_shutdown?
  }
end

def stop_watchers(targets_info, immediate: false, unwatched: false, remove_watcher: true)
  targets_info.each_value { |target_info|
    if remove_watcher
      tw = @tails.delete(target_info)
    else
      tw = @tails[target_info]
    end
    if tw
      tw.unwatched = unwatched
      if immediate
        detach_watcher(tw, target_info.ino, false)
      else
        detach_watcher_after_rotate_wait(tw, target_info.ino)
      end
    end
  }
end

def close_watcher_handles
  @tails.keys.each do |target_info|
    tw = @tails.delete(target_info)
    if tw
      tw.close
    end
  end
end

# refresh_watchers calls @tails.keys so we don't use stop_watcher -> start_watcher sequence for safety.
def update_watcher(target_info, pe)
  log.info("detected rotation of #{target_info.path}; waiting #{@rotate_wait} seconds")

  if @pf
    pe_inode = pe.read_inode
    target_info_from_position_entry = TargetInfo.new(target_info.path, pe_inode)
    unless pe_inode == @pf[target_info_from_position_entry].read_inode
      log.debug "Skip update_watcher because watcher has been already updated by other inotify event"
      return
    end
  end

  rotated_target_info = TargetInfo.new(target_info.path, pe.read_inode)
  rotated_tw = @tails[rotated_target_info]
  new_target_info = target_info.dup

  if @follow_inodes
    new_position_entry = @pf[target_info]

    if new_position_entry.read_inode == 0
      @tails[new_target_info] = setup_watcher(new_target_info, new_position_entry)
      @tails[new_target_info].on_notify
    end
  else
    @tails[new_target_info] = setup_watcher(new_target_info, pe)
    @tails[new_target_info].on_notify
  end
  detach_watcher_after_rotate_wait(rotated_tw, pe.read_inode) if rotated_tw
end

# TailWatcher#close is called by another thread at shutdown phase.
# It causes 'can't modify string; temporarily locked' error in IOHandler
# so adding close_io argument to avoid this problem.
# At shutdown, IOHandler's io will be released automatically after detached the event loop
def detach_watcher(tw, ino, close_io = true)
  tw.watchers.each do |watcher|
    event_loop_detach(watcher)
  end
  tw.detach(@shutdown_start_time)

  tw.close if close_io

  if tw.unwatched && @pf
    target_info = TargetInfo.new(tw.path, ino)
    unwatch_position_target(@pf, target_info)
  end
end

def detach_watcher_after_rotate_wait(tw, ino)
  # Call event_loop_attach/event_loop_detach is high-cost for short-live object.
  # If this has a problem with large number of files, use @_event_loop directly instead of timer_execute.
  if @open_on_every_update
    # Detach now because it's already closed, waiting it doesn't make sense.
    detach_watcher(tw, ino)
  elsif @read_bytes_limit_per_second < 0
    # throttling isn't enabled, just wait @rotate_wait
    timer_execute(:in_tail_close_watcher, @rotate_wait, repeat: false) do
      detach_watcher(tw, ino)
    end
  else
    # When the throttling feature is enabled, it might not reach EOF yet.
    # Should ensure to read all contents before closing it, with keeping throttling.
    start_time_to_wait = Fluent::Clock.now
    timer = timer_execute(:in_tail_close_watcher, 1, repeat: true) do
      elapsed = Fluent::Clock.now - start_time_to_wait
      if tw.eof? && elapsed >= @rotate_wait
        timer.detach
        detach_watcher(tw, ino)
      end
    end
  end
end

def flush_buffer(tw, buf)
  buf.chomp!
  @parser.parse(buf) { |time, record|
    if time && record
      tag = resolve_stream_tag(tw)
      record = decorate_record_with_path(record, tw.path)
      router.emit(tag, time, record)
    else
      if @emit_unmatched_lines
        record = unmatched_line_record(buf)
        record = decorate_record_with_path(record, tail_watcher.path)
        tag = resolve_stream_tag(tw)
        router.emit(tag, Fluent::EventTime.now, record)
      end
      log.warn "got incomplete line at shutdown from #{tw.path}: #{buf.inspect}"
    end
  }
end

# @return true if no error or unrecoverable error happens in emit action. false if got BufferOverflowError
def receive_lines(lines, tail_watcher)
  es = @receive_handler.call(lines, tail_watcher)
  unless event_collector_empty?(es)
    tag = resolve_stream_tag(tail_watcher)
    begin
      router.emit_stream(tag, es)
    rescue Fluent::Plugin::Buffer::BufferOverflowError
      return false
    rescue
      # ignore non BufferQueueLimitError errors because in_tail can't recover. Engine shows logs and backtraces.
      return true
    end
  end

  return true
end

def convert_line_to_event(line, es, tail_watcher)
  begin
    line.chomp!  # remove \n
    @parser.parse(line) { |time, record|
      if time && record
        record = decorate_record_with_path(record, tail_watcher.path)
        append_parsed_event(es, time, record)
      else
        if @emit_unmatched_lines
          record = unmatched_line_record(line)
          record = decorate_record_with_path(record, tail_watcher.path)
          append_parsed_event(es, Fluent::EventTime.now, record)
        end
        log.warn "pattern not matched: #{line.inspect}"
      end
    }
  rescue => e
    log.warn 'invalid line found', file: tail_watcher.path, line: line, error: e.to_s
    log.debug_backtrace(e.backtrace)
  end
end

def parse_singleline(lines, tail_watcher)
  es = open_event_collector
  lines.each { |line|
    convert_line_to_event(line, es, tail_watcher)
  }
  finish_event_collector(es)
end

# No need to check if line_buffer_timer_flusher is nil, since line_buffer_timer_flusher should exist
def parse_multilines(lines, tail_watcher)
  lb = tail_watcher.line_buffer_timer_flusher.line_buffer
  es = open_event_collector
  if @parser.has_firstline?
    tail_watcher.line_buffer_timer_flusher.reset_timer
    lines.each { |line|
      if @parser.firstline?(line)
        if lb
          convert_line_to_event(lb, es, tail_watcher)
        end
        lb = line
      else
        if lb.nil?
          if @emit_unmatched_lines
            convert_line_to_event(line, es, tail_watcher)
          end
          log.warn "got incomplete line before first line from #{tail_watcher.path}: #{line.inspect}"
        else
          lb << line
        end
      end
    }
  else
    lb ||= ''
    lines.each do |line|
      lb << line
      @parser.parse(lb) { |time, record|
        if time && record
          convert_line_to_event(lb, es, tail_watcher)
          lb = ''
        end
      }
    end
  end
  tail_watcher.line_buffer_timer_flusher.line_buffer = lb
  finish_event_collector(es)
end

def attach_position_file_owner(position_file)
  @position_catalog ||= {}
  @position_guard ||= Mutex.new
  @position_handle = position_file
  @position_follow_flag = position_file.follow_inodes
  @position_log_sink = position_file.logger
  @position_last_compact_size = nil
  @position_last_compact_mtime = nil
  @position_unwatched_keys = []
  @position_load_generation = (@position_load_generation || 0) + 1
  @position_guard.synchronize do
    @position_catalog.clear unless @position_catalog.empty?
    position_file.owner = self
    @position_handle
  end
end

def fetch_position_entry(position_file, target_info)
  @position_catalog ||= {}
  @position_guard ||= Mutex.new
  @position_handle = position_file
  @position_follow_flag = position_file.follow_inodes
  key = position_storage_key(target_info, @position_follow_flag)
  @position_guard.synchronize do
    entry = TailInput.lookup_position_entry(
      position_file.file,
      position_file.file_mutex,
      position_file.map,
      position_file.follow_inodes,
      target_info
    )
    remember_position_entry(key, entry)
    entry
  end
end

def remember_position_entry(key, entry)
  @position_catalog ||= {}
  @position_guard ||= Mutex.new
  if key.nil? || entry.nil?
    return entry
  end
  @position_catalog[key] = entry
  if @position_unwatched_keys && @position_unwatched_keys.include?(key)
    @position_unwatched_keys.delete(key)
  end
  entry
end

def unwatch_position_target(position_file, target_info)
  @position_catalog ||= {}
  @position_guard ||= Mutex.new
  @position_handle = position_file
  @position_follow_flag = position_file.follow_inodes
  key = position_storage_key(target_info, @position_follow_flag)
  @position_guard.synchronize do
    TailInput.unwatch_position_entry(
      position_file.map,
      position_file.follow_inodes,
      target_info
    )
    note_unwatched_position(key)
    @position_catalog.delete(key)
  end
end

def reload_position_catalog(position_file, existing_targets = nil)
  @position_catalog ||= {}
  @position_guard ||= Mutex.new
  @position_handle = position_file
  @position_follow_flag = position_file.follow_inodes
  @position_log_sink = position_file.logger
  @position_guard.synchronize do
    map = TailInput.load_position_map(
      position_file.file,
      position_file.file_mutex,
      position_file.follow_inodes,
      existing_targets,
      position_file.logger
    )
    position_file.replace_map(map)
    @position_catalog = map.dup
    @position_load_generation = (@position_load_generation || 0) + 1
    @position_catalog
  end
end

def compact_position_file(position_file)
  @position_catalog ||= {}
  @position_guard ||= Mutex.new
  @position_handle = position_file
  @position_follow_flag = position_file.follow_inodes
  @position_log_sink = position_file.logger
  snapshot = TailInput.capture_position_file_identity(position_file.file, position_file.file_mutex)
  entries = position_file.send(:fetch_compacted_entries)
  position_file.file_mutex.synchronize do
    if should_rewrite_position_file?(position_file, snapshot[0], snapshot[1])
      TailInput.rewrite_position_file(position_file.file, position_file.file_mutex, position_file.map, entries, locked: true)
    end
  end
  reload_position_index(entries)
  entries
end

def position_storage_key(target_info, follow = nil)
  @position_catalog ||= {}
  follow_flag = follow.nil? ? @position_follow_flag : follow
  if target_info.nil?
    return nil
  end
  if follow_flag
    target_info.ino
  else
    target_info.path
  end
end

def note_unwatched_position(key)
  @position_catalog ||= {}
  @position_unwatched_keys ||= []
  @position_load_generation ||= 0
  if key.nil?
    return @position_unwatched_keys
  end
  unless @position_unwatched_keys.include?(key)
    @position_unwatched_keys << key
  end
  @position_catalog.delete(key)
  @position_unwatched_keys
end

def should_rewrite_position_file?(position_file, size, mtime)
  @position_catalog ||= {}
  @position_handle = position_file
  current_size = position_file.file.size
  current_mtime = position_file.file.mtime
  if current_size != size
    false
  elsif current_mtime != mtime
    false
  else
    @position_last_compact_size = current_size
    @position_last_compact_mtime = current_mtime
    true
  end
end

def reload_position_index(entries)
  @position_catalog ||= {}
  @position_guard ||= Mutex.new
  @position_load_generation = (@position_load_generation || 0) + 1
  if entries.nil?
    return @position_catalog
  end
  entries.each do |key, value|
    if value
      @position_catalog[key] = value
    end
  end
  @position_catalog
end

def prepare_file_access_policy(capability)
  @access_cache ||= {}
  @access_guard ||= Mutex.new
  @access_probe = capability
  @access_cache[:probe] = capability
  @access_denied_paths = []
  @access_granted = false
  @access_dac_search = false
  @access_dac_override = false
  @access_probe_usable = capability ? capability.usable? : false
  @access_cache_generation = 0
  refresh_capability_flags
  @access_probe
end

def path_is_readable?(path)
  @access_cache ||= {}
  if path.nil? || path.empty?
    @access_cache[:last_path] = path
    return false
  end
  @access_cache[:last_path] = path
